ALTER TABLE "PUBLIC"."TB_AUDITORIA_CORRECAO_FREQUENCIA" ADD CONSTRAINT "PUBLIC"."CK_CORRECAO_INTEGRIDADE" CHECK(("PERFIL" IN('ADMINISTRADOR', 'PROFISSIONAL'))
    AND ("FREQUENCIA_ANTERIOR" IN('PRESENTE', 'FALTOU'))
    AND ("FREQUENCIA_NOVA" IN('PRESENTE', 'FALTOU'))
    AND ("VERSAO_ANTERIOR" >= 0)
    AND (CHAR_LENGTH(TRIM("UNIDADE")) > 0)
    AND ("FREQUENCIA_ANTERIOR" <> "FREQUENCIA_NOVA")
    AND (CHAR_LENGTH(TRIM("JUSTIFICATIVA")) BETWEEN 10 AND 2000)
    AND ("VERSAO_RESULTANTE" > "VERSAO_ANTERIOR")
    AND ((("TIPO_CORRECAO" = 'INDIVIDUAL')
    AND ("AGENDAMENTO_ID" IS NOT NULL)
    AND ("SESSAO_ID" IS NULL)
    AND ("PARTICIPANTE_ID" IS NULL)
    AND ("SITUACAO_RESERVA" IS NOT NULL)
    AND ("SITUACAO_SESSAO" IS NULL))
    OR (("TIPO_CORRECAO" = 'GRUPO')
    AND ("AGENDAMENTO_ID" IS NULL)
    AND ("SESSAO_ID" IS NOT NULL)
    AND ("PARTICIPANTE_ID" IS NOT NULL)
    AND ("SITUACAO_RESERVA" IS NULL)
    AND ("SITUACAO_SESSAO" = 'REALIZADA')))) NOCHECK;
ALTER TABLE "PUBLIC"."TB_AGENDAMENTO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_2" CHECK("SITUACAO_ATENDIMENTO" IN(1, 2, 3, 4, 5, 6)) NOCHECK;
