ALTER TABLE "PUBLIC"."TB_AUDITORIA_CORRECAO_FREQUENCIA" ADD CONSTRAINT "PUBLIC"."CK_CORRECAO_GRUPO_CONFIRMADO" CHECK(("TIPO_CORRECAO" <> 'GRUPO')
