ALTER TABLE "PUBLIC"."TB_PACIENTE_AUD" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5" CHECK("CAPS_REFERENCIA" IN(1, 2, 3)) NOCHECK;
