ALTER TABLE "PUBLIC"."TB_AUDITORIA_BUSCA_ATIVA" ADD CONSTRAINT "PUBLIC"."CK_EVENTO_BUSCA_INTEGRIDADE" CHECK(("PERFIL" IN('ADMINISTRADOR', 'PROFISSIONAL', 'RECEPCAO'))
    AND ("QUANTIDADE" >= 0)
    AND (FALSE IN("GATILHO_CONFIRMADO", "INDICADORES_PENDENTES"))
    AND (CHAR_LENGTH(TRIM("UNIDADE")) > 0)
    AND ((("TIPO_EVENTO" = 'CONSULTA_LISTA_BUSCA_ATIVA')
    AND ("PACIENTE_ID" IS NULL)
    AND ("DESTINO" IS NULL)
    AND ("DESCRICAO" IS NULL))
    OR (("TIPO_EVENTO" = 'VISUALIZACAO_ALERTA')
    AND ("PACIENTE_ID" IS NOT NULL)
    AND ("DESTINO" IS NULL)
    AND ("DESCRICAO" IS NULL)
    AND ("QUANTIDADE" = 1))
    OR (("PERFIL" IN('ADMINISTRADOR', 'PROFISSIONAL'))
    AND ("TIPO_EVENTO" = 'ENCAMINHAMENTO_ALERTA')
    AND ("PACIENTE_ID" IS NOT NULL)
    AND ("DESTINO" IS NOT NULL)
    AND ("DESCRICAO" IS NOT NULL)
    AND ("QUANTIDADE" = 1)
    AND ("INDICADORES_PENDENTES" = FALSE)
    AND (CHAR_LENGTH(TRIM("DESTINO")) BETWEEN 1 AND 200)
    AND (CHAR_LENGTH(TRIM("DESCRICAO")) BETWEEN 10 AND 1000)))) NOCHECK;
